   378|/**
   379| * Idempotent registration orchestrator.
   380| *
   381| * One `registrationRequestId` always maps to at most one logical registration:
   382| *  - duplicate submissions return the existing result
   383| *  - a timed-out client can call again with the same ID and resume
   384| *  - partial failures (Auth ok, profile missing) are repaired, not duplicated
   385| */
   386|export async function orchestrateRegistration(
   387|  input: RegistrationRequestInput
   388|): Promise<NormalizedRegistrationResult> {
   389|  const traceId = generateTraceId();
   390|  const registrationRequestId = input.registrationRequestId || randomUUID();
   391|  const normalizedEmail = normalizeEmail(input.email);
   392|  const emailHash = hashEmail(normalizedEmail);
   393|
   394|  // Step 1: validate (never calls backend)
   395|  if (!input.firstName || !input.lastName) {
   396|    return makeError('INVALID_EMAIL', 'VALIDATING', traceId, registrationRequestId, {
   397|      message: 'First name and last name are required.',
   398|      retryable: false,
   399|    });
   400|  }
   401|  if (!isValidEmail(normalizedEmail)) {
   402|    return makeError('INVALID_EMAIL', 'VALIDATING', traceId, registrationRequestId, { retryable: false });
   403|  }
   404|  const pwCheck = validatePasswordPolicy(input.password);
   405|  if (!pwCheck.valid) {
   406|    return makeError('WEAK_PASSWORD', 'VALIDATING', traceId, registrationRequestId, {
   407|      message: pwCheck.reason ?? 'Password does not meet requirements.',
   408|      retryable: false,
   409|    });
   410|  }
   411|  if (!input.acceptTerms) {
   412|    return makeError('UNKNOWN_ERROR', 'VALIDATING', traceId, registrationRequestId, {
   413|      message: 'You must accept the Terms of Service.',
   414|      retryable: false,
   415|    });
   416|  }
   417|
   418|  // Step 2: idempotency — resume an existing in-flight or completed request
   419|  const existing = await loadRegistrationState(registrationRequestId);
   420|  if (existing && existing.finalStatus === 'completed' && existing.authUserId) {
   421|    // Duplicate submission for an already-completed request → return the same result.
   422|    return {
   423|      ok: true,
   424|      stage: 'COMPLETED',
   425|      registrationRequestId,
   426|      traceId,
   427|      authUserId: existing.authUserId,
   428|      email: normalizedEmail,
   429|      requiresVerification: false,
   430|      resumeToken: existing.registrationRequestId,
   431|    };
   432|  }
   433|  if (existing && existing.finalStatus === 'pending' && existing.stage === 'AUTH_CREATING') {
   434|    // A previous call crashed mid-auth — do NOT blindly create a second user.
   435|    // Surface a recoverable error so the client can poll status and resume.
   436|    return makeError('AUTH_CREATION_FAILED', 'AUTH_CREATING', traceId, registrationRequestId, {
   437|      message: 'A previous attempt is still being processed. Please wait a moment and try again.',
   438|      retryable: true,
   439|    });
   440|  }
