   708|  const failed = states.filter((s) => s.finalStatus === 'failed').length;
   709|  const rateLimited = states.filter((s) => s.lastErrorCode === 'RATE_LIMITED').length;
   710|  const abandoned = states.filter((s) => s.finalStatus === 'pending' && (Date.now() - new Date(s.updatedAt).getTime()) > 30 * 60 * 1000).length;
