const ALLOWED_MIGRATIONS: Record<string, string> = {
  'IVX-ENTERPRISE-REGISTRATION': path.join(process.cwd(), 'expo', 'supabase', 'IVX-ENTERPRISE-REGISTRATION.sql'),
